def media_minutos(sessoes):
    if len(sessoes) == 0:
        return 0.0
    return sum(sessoes) / len(sessoes)

assert media_minutos([]) == 0.0
assert media_minutos([20, 30]) == 25.0
print(f"Média: {media_minutos([20, 30]):.1f} min")

exercise.solution:
def media_minutos(sessoes):
    if not sessoes:
        return 0.0
    return sum(sessoes) / len(sessoes)

sessoes = []
minutos = int(input())
while minutos != 0:
    if minutos > 0:
        sessoes.append(minutos)
    minutos = int(input())

print(f"Sessões: {len(sessoes)}")
print(f"Total: {sum(sessoes)} min")
print(f"Média: {media_minutos(sessoes):.1f} min")
